def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])

    # Find the vertical separator: the column containing the most cells
    # of one non-zero colour.
    best = None
    for c in range(w):
        counts = {}
        total_nz = 0
        for r in range(h):
            v = grid[r][c]
            if v != 0:
                total_nz += 1
                counts[v] = counts.get(v, 0) + 1
        if counts:
            best_colour = max(counts, key=lambda x: (counts[x], x))
            best_count = counts[best_colour]
            key = (best_count, total_nz)
            if best is None or key > best[0]:
                best = (key, c, best_colour)

    sep_col = best[1]
    sep_colour = best[2]

    out = [row[:] for row in grid]

    # Global preference if a row has objects on both sides.
    left_total = 0
    right_total = 0
    for r in range(h):
        for c in range(w):
            if c == sep_col:
                continue
            if grid[r][c] != 0:
                if c < sep_col:
                    left_total += 1
                else:
                    right_total += 1
    global_side = "left" if left_total >= right_total else "right"

    def parse_blocks(cells_from_near_to_far):
        """
        Returns a list of (colour, length) blocks ordered from the block
        nearest to the separator outward.
        """
        blocks = []
        cur_colour = 0
        cur_len = 0

        for v in cells_from_near_to_far:
            if v != 0:
                if v == cur_colour:
                    cur_len += 1
                else:
                    if cur_colour != 0:
                        blocks.append((cur_colour, cur_len))
                    cur_colour = v
                    cur_len = 1
            else:
                if cur_colour != 0:
                    blocks.append((cur_colour, cur_len))
                cur_colour = 0
                cur_len = 0

        if cur_colour != 0:
            blocks.append((cur_colour, cur_len))

        return blocks

    for r in range(h):
        left_cells = [grid[r][c] for c in range(sep_col)]
        right_cells = [grid[r][c] for c in range(sep_col + 1, w)]

        left_nz = sum(v != 0 for v in left_cells)
        right_nz = sum(v != 0 for v in right_cells)

        if left_nz == 0 and right_nz == 0:
            continue

        # Decide which side is the source side for this row.
        if left_nz > 0 and right_nz == 0:
            side = "left"
        elif right_nz > 0 and left_nz == 0:
            side = "right"
        else:
            side = global_side

        if side == "left":
            source = list(reversed(left_cells))       # near separator first
            target_len = w - sep_col - 1
        else:
            source = list(right_cells)                # near separator first
            target_len = sep_col

        blocks = parse_blocks(source)
        if not blocks:
            continue

        # Build the generated pattern.
        seq = [0] * target_len
        for t in range(target_len):
            for colour, length in blocks:
                if t % length == 0:
                    seq[t] = colour
                    break

        # Write into the target side, starting adjacent to the separator.
        if side == "left":
            for t in range(target_len):
                c = sep_col + 1 + t
                out[r][c] = seq[t]
        else:
            for t in range(target_len):
                c = sep_col - 1 - t
                out[r][c] = seq[t]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])

    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if 0 < r < h - 1 and 0 < c < w - 1:
                if (
                    grid[r][c] == 4
                    and grid[r - 1][c] == 4
                    and grid[r + 1][c] == 4
                    and grid[r][c - 1] == 4
                    and grid[r][c + 1] == 4
                ):
                    out[r][c] = 8
                    out[r - 1][c] = 8
                    out[r + 1][c] = 8
                    out[r][c - 1] = 8
                    out[r][c + 1] = 8

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Find the separator column: the column containing the longest vertical
    # run of a single non-background color.
    best_col = -1
    best_color = -1
    best_len = 0

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == 0:
                r += 1
                continue
            color = grid[r][c]
            start = r
            while r < h and grid[r][c] == color:
                r += 1
            length = r - start
            if length > best_len:
                best_len = length
                best_col = c
                best_color = color

    if best_col < 0 or best_len <= 0:
        return out

    sep_col = best_col
    sep_color = best_color

    # Decide which side is the source side: the side containing more non-zero
    # cells outside the separator column.
    left_nonzero = 0
    right_nonzero = 0
    for r in range(h):
        for c in range(sep_col):
            if grid[r][c] != 0:
                left_nonzero += 1
        for c in range(sep_col + 1, w):
            if grid[r][c] != 0:
                right_nonzero += 1

    source_left = left_nonzero >= right_nonzero

    # Process each row where the separator line is present.
    for r in range(h):
        if grid[r][sep_col] != sep_color:
            continue

        runs = []

        if source_left:
            c = sep_col - 1
            while c >= 0:
                if grid[r][c] == 0:
                    c -= 1
                    continue
                color = grid[r][c]
                start = c
                while c >= 0 and grid[r][c] == color:
                    c -= 1
                end = start
                length = end - c
                # Distance order: farther runs first, nearer runs later (overwrite).
                runs.append((-c, color, length))
        else:
            c = sep_col + 1
            while c < w:
                if grid[r][c] == 0:
                    c += 1
                    continue
                color = grid[r][c]
                start = c
                while c < w and grid[r][c] == color:
                    c += 1
                end = c - 1
                length = end - start + 1
                # Farther runs first, nearer runs later (overwrite).
                runs.append((c, color, length))

        if not runs:
            continue

        # Farthest to nearest.
        runs.sort(key=lambda x: x[0], reverse=True)

        if source_left:
            # Target is on the right; position 0 is sep_col + 1.
            for _, color, length in runs:
                for pos in range(0, w - sep_col - 1, length):
                    out[r][sep_col + 1 + pos] = color
        else:
            # Target is on the left; position 0 is sep_col - 1.
            for _, color, length in runs:
                for pos in range(0, sep_col, length):
                    out[r][sep_col - 1 - pos] = color

    return out

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])
    visited = [[False] * W for _ in range(H)]
    objects = []
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    # Find connected monochromatic components.
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0 or visited[r][c]:
                continue

            color = grid[r][c]
            q = deque([(r, c)])
            visited[r][c] = True

            top = bottom = r
            left = right = c
            cells = 0

            while q:
                x, y = q.popleft()
                cells += 1
                top = min(top, x)
                bottom = max(bottom, x)
                left = min(left, y)
                right = max(right, y)

                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < H and 0 <= ny < W:
                        if not visited[nx][ny] and grid[nx][ny] == color:
                            visited[nx][ny] = True
                            q.append((nx, ny))

            n = bottom - top + 1
            if n != right - left + 1 or n < 2:
                continue

            total = n * n
            border = total - (n - 2) ** 2 if n > 2 else total
            kind = None

            if cells == total:
                kind = "solid"
            elif cells == border:
                ok = True
                for rr in range(top + 1, bottom):
                    for cc in range(left + 1, right):
                        if grid[rr][cc] != 0:
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    kind = "hollow"

            if kind is None:
                continue

            tile = [list(grid[rr][left:left + n]) for rr in range(top, top + n)]
            objects.append((kind, top, left, n, tile))

    hollows = [o for o in objects if o[0] == "hollow"]
    solids = [o for o in objects if o[0] == "solid"]

    hollows.sort(key=lambda o: (o[1], o[2]))
    solids.sort(key=lambda o: (o[1], o[2]))

    blocks = max(len(hollows), len(solids))
    if blocks == 0:
        return []

    size = max(o[3] for o in objects)
    out = [[0] * (2 * size) for _ in range(blocks * size)]

    def place(tile, row0, col0):
        k = len(tile)
        for i in range(k):
            for j in range(k):
                out[row0 + i][col0 + j] = tile[i][j]

    for i, (_, _, _, _, tile) in enumerate(hollows):
        place(tile, i * size, 0)

    for i, (_, _, _, _, tile) in enumerate(solids):
        place(tile, i * size, size)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Background is the most common colour (7 in the examples).
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=lambda c: counts[c])

    out = [row[:] for row in grid]

    def is_fg(r, c):
        return 0 <= r < h and 0 <= c < w and grid[r][c] != bg

    marks = set()

    # Type A: 2x2 diagonal pair of foreground pixels.
    # Mark the top empty cell of the 2x2 block.
    for r in range(h - 1):
        for c in range(w - 1):
            a = grid[r][c]
            b = grid[r][c + 1]
            d = grid[r + 1][c]
            e = grid[r + 1][c + 1]

            # top-right / bottom-left diagonal
            if b != bg and d != bg and a == bg and e == bg:
                marks.add((r, c))
            # top-left / bottom-right diagonal
            if a != bg and e != bg and b == bg and d == bg:
                marks.add((r, c + 1))

    # Type B: 2x2 L-shape made of three foreground pixels.
    # Mark the empty corner of the 2x2 block.
    for r in range(h - 1):
        for c in range(w - 1):
            a = grid[r][c]
            b = grid[r][c + 1]
            d = grid[r + 1][c]
            e = grid[r + 1][c + 1]
            vals = [a, b, d, e]

            if vals.count(bg) == 1:
                if a == bg:
                    marks.add((r, c))
                elif b == bg:
                    marks.add((r, c + 1))
                elif d == bg:
                    marks.add((r + 1, c))
                else:
                    marks.add((r + 1, c + 1))

    # Output colour: 9 unless 9 is already present, then use 1.
    present = set()
    for row in grid:
        for v in row:
            present.add(v)
    paint = 1 if 9 in present else 9

    # Move every marked point up by 5 and left by 5; if it remains inside,
    # paint that single cell.
    for r, c in marks:
        nr = r - 5
        nc = c - 5
        if 0 <= nr < h and 0 <= nc < w:
            out[nr][nc] = paint

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # The fixed outer rectangular frame occupies rows 0..H-1 and cols 9..W-1.
    # Only the 5s strictly inside that frame are "free" and move.
    def is_frame(r: int, c: int) -> bool:
        return r in (0, H - 1) or c in (9, W - 1)

    free_5s = []
    other_cells = []

    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v == 5 and not is_frame(r, c):
                free_5s.append((r, c))
            elif v != 0 and not (v == 5 and is_frame(r, c)):
                other_cells.append((r, c, v))

    # All non-border 5s move 10 columns to the right.
    out = [[0] * W for _ in range(H)]
    for r, c in free_5s:
        out[r][c + 10] = 5

    # Restore the fixed frame.
    for r in range(H):
        for c in range(9, W):
            if r == 0 or r == H - 1 or c == 9 or c == W - 1:
                out[r][c] = 5

    # Non-5 colours in the frame interior are pushed upward, cell by cell,
    # into the nearest empty cell above their original position.
    for r, c, v in other_cells:
        target = r
        while target > 0 and out[target][c] == 0:
            target -= 1
        out[target][c] = v

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])
    container_left = 9
    container_right = W - 1
    container_top = 1
    container_bottom = H - 2

    # Step 1: Extract triangle shape from left side (cols 0-8)
    left_5s = set()
    for r in range(H):
        for c in range(9):
            if grid[r][c] == 5:
                left_5s.add((r, c))

    if left_5s:
        rows = sorted(set(r for r, c in left_5s))
        cols = sorted(set(c for r, c in left_5s))
        min_r, max_r = rows[0], rows[-1]
        min_c, max_c = cols[0], cols[-1]
        tri_height = max_r - min_r + 1
        tri_width = max_c - min_c + 1
        triangle = set()
        for r in range(tri_height):
            for c in range(tri_width):
                if (min_r + r, min_c + c) in left_5s:
                    triangle.add((r, c))
    else:
        triangle = set()
        tri_height = 0
        tri_width = 0

    # Step 2: Build output - copy frame and background
    out = [[0] * W for _ in range(H)]
    for r in range(H):
        for c in range(container_left, container_right + 1):
            if r == 0 or r == container_bottom + 1 or c == container_left or c == container_right:
                out[r][c] = 5

    # Step 3: Place triangle at bottom-center of container
    tri_top = container_bottom - tri_height + 1
    tri_col_offset = container_left + 1 + (7 - tri_width) // 2
    for (tr, tc) in triangle:
        out[tri_top + tr][tri_col_offset + tc] = 5

    # Step 4: Collect colored cells from container interior and compact upward
    for c in range(container_left + 1, container_right):
        cells = []
        for r in range(container_top, container_bottom + 1):
            v = grid[r][c]
            if v != 0 and v != 5:
                cells.append(v)
        write_r = container_top
        for v in cells:
            while write_r <= container_bottom and out[write_r][c] == 5:
                write_r += 1
            if write_r <= container_bottom:
                out[write_r][c] = v
            write_r += 1

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.asarray(grid, dtype=int)
    H, W = a.shape
    n_rows, n_cols = H // 6, W // 6

    decoded = []
    for i in range(n_rows):
        row_dec = []
        for j in range(n_cols):
            block = a[i * 6:(i + 1) * 6, j * 6:(j + 1) * 6]

            # Find the distinctive 3x4 zero rectangle.
            rect = False
            has_six = False
            for r in range(block.shape[0] - 3 + 1):
                for c in range(block.shape[1] - 4 + 1):
                    if not np.any(block[r:r + 3, c:c + 4]):
                        rect = True
            if block[0, 4] == 6 and block[0, 8] == 6:
                has_six = True

            if rect and has_six:
                row_dec.append(6)
            elif rect:
                row_dec.append(2)
            else:
                row_dec.append(0)
        decoded.append(row_dec)

    d = np.asarray(decoded, dtype=int)

    # Crop fully empty border rows/columns, as in Example 2.
    if d.size == 0:
        return []

    rows = np.where(np.any(d != 0, axis=1))[0]
    cols = np.where(np.any(d != 0, axis=0))[0]
    if len(rows) == 0 or len(cols) == 0:
        return d.tolist()

    r0, r1 = rows[0], rows[-1] + 1
    c0, c1 = cols[0], cols[-1] + 1
    return d[r0:r1, c0:c1].tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    H, W = len(grid), len(grid[0])
    br, bc = 6, 6
    R, C = H // br, W // bc

    decoded = [[0] * C for _ in range(R)]

    for i in range(R):
        for j in range(C):
            block = [
                [grid[r][c] for c in range(j * bc, (j + 1) * bc)]
                for r in range(i * br, (i + 1) * br)
            ]

            # The non-background special colours are the nonzero digits that
            # appear inside 6x6 markers: 6 in example 1, 8 in example 2, etc.
            special = [
                val
                for row in block
                for val in row
                if val != 0 and val not in (1, 2, 3, 4)
            ]

            if not special:
                decoded[i][j] = 0
            else:
                # Decode the marker by its most common special colour.
                # In the given examples this is the colour that forms the marker
                # border/corners and becomes the output cell value.
                best = max(set(special), key=lambda v: special.count(v))
                decoded[i][j] = best

    # Crop fully empty border rows/columns, e.g. example 2 becomes 4x4.
    rows = [i for i in range(R) if any(x != 0 for x in decoded[i])]
    cols = [j for j in range(C) if any(decoded[i][j] != 0 for i in range(R))]

    if not rows or not cols:
        return [[0] * len(cols) for _ in range(len(rows))]

    r0, r1 = rows[0], rows[-1] + 1
    c0, c1 = cols[0], cols[-1] + 1

    return [
        [decoded[i][j] for j in range(c0, c1)]
        for i in range(r0, r1)
    ]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])

    # The border colour is the value on the outer edge.
    border = grid[0][0]

    # Find every horizontal border line: rows that are uniformly the border colour.
    border_rows = [r for r in range(H) if all(grid[r][c] == border for c in range(W))]
    # Find every vertical border line: columns that are uniformly the border colour.
    border_cols = [c for c in range(W) if all(grid[r][c] == border for r in range(H))]

    if len(border_rows) < 2 or len(border_cols) < 2:
        # Fallback for any degenerate case: return the input as a new list.
        return [list(row) for row in grid]

    # Consecutive border lines delimit one row or column of cells.
    row_spans = list(zip(border_rows, border_rows[1:]))
    col_spans = list(zip(border_cols, border_cols[1:]))

    def cell(r0, r1, c0, c1):
        """Extract the interior of a cell (without its surrounding border)."""
        return [
            [grid[r][c] for c in range(c0 + 1, c1)]
            for r in range(r0 + 1, r1)
        ]

    # For every row of cells, choose the single cell that differs from the rest.
    # If all cells in that row are identical, choose the first one.
    result = []
    for r0, r1 in row_spans:
        candidates = [cell(r0, r1, c0, c1) for c0, c1 in col_spans]

        chosen = 0
        for i in range(len(candidates)):
            if not all(candidates[j] == candidates[i] for j in range(len(candidates)) if j != i):
                chosen = i
                break

        chosen_cell = candidates[chosen]

        # Rebuild the output grid row by row, preserving all horizontal border lines.
        for r in range(border_rows[0], border_rows[-1] + 1):
            if r in border_rows:
                result.append([border] * (len(chosen_cell[0]) + 2))
            else:
                # Locate which interior row of the chosen cell corresponds to this grid row.
                for local_r in range(len(chosen_cell)):
                    if r0 + 1 + local_r == r:
                        result.append([border] + list(chosen_cell[local_r]) + [border])
                        break

    return result

