from collections import deque

def transform(grid):
    g = [list(row) for row in grid]
    H = len(g)
    W = len(g[0]) if H else 0

    # Find the marker line made of 4s
    four = [(r, c) for r in range(H) for c in range(W) if g[r][c] == 4]
    if not four:
        return g

    rows4 = {r for r, c in four}
    cols4 = {c for r, c in four}

    horizontal = (max(rows4) - min(rows4) < max(cols4) - min(cols4)) or len(rows4) <= 1

    if horizontal:
        mrow = max(rows4)  # examples put marker at an edge; use bottom edge
        left = min(c for r, c in four if r == mrow)
        right = max(c for r, c in four if r == mrow)
        width = right - left + 1
    else:
        mcol = min(cols4)  # examples put marker at left edge
        top = min(r for r, c in four if c == mcol)
        bottom = max(r for r, c in four if c == mcol)
        height = bottom - top + 1

    # Background colour: most frequent non-4 colour
    from collections import Counter
    cnt = Counter(g[r][c] for r in range(H) for c in range(W) if g[r][c] != 4)
    bg = cnt.most_common(1)[0][0] if cnt else 0

    fg = [[g[r][c] != bg and g[r][c] != 4 for c in range(W)] for r in range(H)]

    # Connected components of foreground (orthogonal)
    seen = [[False] * W for _ in range(H)]
    comps = []
    for r in range(H):
        for c in range(W):
            if fg[r][c] and not seen[r][c]:
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and fg[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx] = True
                            q.append((ny, nx))
                comps.append(cells)

    out = [[bg] * W for _ in range(H)]

    def fill_line(out, r, c0, c1, col):
        out[r][c0] = col
        for x in range(c0 + 1, c1 + 1):
            out[r][x] = col

    for cells in comps:
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)

        if horizontal:
            stripe_c0 = left
            stripe_c1 = right
            stripe_r0 = min_r
            stripe_r1 = max_r

            # Preserve component cells that will not be overwritten
            for r, c in cells:
                in_stripe = stripe_r0 <= r <= stripe_r1 and stripe_c0 <= c <= stripe_c1
                if not in_stripe:
                    out[r][c] = g[r][c]

            # Vertical dashed stripe inside component, extended to even rows
            s0 = min_r
            if s0 % 2 == 1:
                s0 -= 1
            s1 = max_r
            if s1 % 2 == 1:
                s1 += 1

            for r in range(s0, s1 + 1, 2):
                if 0 <= r < H:
                    color = 3 if r % 6 == 0 else 4
                    fill_line(out, r, stripe_c0, stripe_c1, color)

            # Every 6th row: paint foreground runs touching the stripe
            for r in range(s0, s1 + 1):
                if 0 <= r < H and r % 6 == 0:
                    # contiguous foreground runs in this row
                    c = min_c
                    while c <= max_c:
                        if fg[r][c]:
                            c0 = c
                            while c <= max_c and fg[r][c]:
                                c += 1
                            c1 = c - 1
                            # If run touches or overlaps stripe, paint it (and bridge to stripe)
                            if c1 >= stripe_c0 - 1 and c0 <= stripe_c1 + 1:
                                cc0 = min(c0, stripe_c0)
                                cc1 = max(c1, stripe_c1)
                                color = 3 if r % 6 == 0 else 4
                                fill_line(out, r, cc0, cc1, color)
                        else:
                            c += 1
        else:
            stripe_r0 = top
            stripe_r1 = bottom
            stripe_c0 = min_c
            stripe_c1 = max_c

            for r, c in cells:
                in_stripe = stripe_r0 <= r <= stripe_r1 and stripe_c0 <= c <= stripe_c1
                if not in_stripe:
                    out[r][c] = g[r][c]

            c0s = min_c
            if c0s % 2 == 1:
                c0s -= 1
            c1s = max_c
            if c1s % 2 == 1:
                c1s += 1

            for c in range(c0s, c1s + 1, 2):
                if 0 <= c < W:
                    color = 3 if c % 6 == 0 else 4
                    for r in range(stripe_r0, stripe_r1 + 1):
                        if 0 <= r < H:
                            out[r][c] = color

            for c in range(c0s, c1s + 1):
                if 0 <= c < W and c % 6 == 0:
                    r = min_r
                    while r <= max_r:
                        if fg[r][c]:
                            r0 = r
                            while r <= max_r and fg[r][c]:
                                r += 1
                            r1 = r - 1
                            if r1 >= stripe_r0 - 1 and r0 <= stripe_r1 + 1:
                                rr0 = min(r0, stripe_r0)
                                rr1 = max(r1, stripe_r1)
                                color = 3 if c % 6 == 0 else 4
                                for rr in range(rr0, rr1 + 1):
                                    if 0 <= rr < H:
                                        out[rr][c] = color
                        else:
                            r += 1

    # Restore the marker line exactly as input
    for r, c in four:
        out[r][c] = 4

    return out

