            _fill_box(a, r0, c0, r1, c1, color)

    return a.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    H, W = a.shape
    out = a.copy()

    # collect connected components of each non-zero color
    seen = np.zeros((H, W), dtype=bool)
    comps = []

    for c in range(1, 10):
        mask = (a == c)
        m = mask.copy()
        while m.any():
            sr, sc = np.argwhere(m)[0]
            stack = [(sr, sc)]
            m[sr, sc] = False
            cells = []
            while stack:
                r, q = stack.pop()
                cells.append((r, q))
                for dr, dq in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    rr, qq = r + dr, q + dq
                    if 0 <= rr < H and 0 <= qq < W and m[rr, qq]:
                        m[rr, qq] = False
                        stack.append((rr, qq))
            comps.append((c, cells))

    l_shapes = {}
    dots = {}
    for c, cells in comps:
        if len(cells) == 3:
            rs = [r for r, _ in cells]
            cs = [q for _, q in cells]
            if max(rs) - min(rs) == 1 and max(cs) - min(cs) == 1:
                l_shapes[c] = cells
                continue
        if len(cells) == 1:
            dots[c] = cells[0]

    # Bresenham integer line, endpoints inclusive
    def bresenham(r0, c0, r1, c1):
        pts = []
        dr = abs(r1 - r0)
        dc = abs(c1 - c0)
        sr = 1 if r1 > r0 else -1
        sc = 1 if c1 > c0 else -1
        err = dr - dc
        r, q = r0, c0
        while True:
            pts.append((r, q))
            if r == r1 and q == c1:
                break
            e2 = 2 * err
            if e2 > -dc:
                err -= dc
                r += sr
            if e2 < dr:
                err += dr
                q += sc
        return pts

    # For each L shape, choose the diagonal from its 2x2 corner toward the dot
    # and draw it until it hits the grid boundary.
    for c, cells in l_shapes.items():
        rs = [r for r, _ in cells]
        cs = [q for _, q in cells]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)

        # the three occupied cells determine the corner cell
        # missing corner is the one not present in the 2x2 square
        corner = None
        for r in (r0, r1):
            for q in (c0, c1):
                if (r, q) in cells:
                    # corner is the cell adjacent to two other cells
                    n = sum(
                        1
                        for dr, dq in ((1, 0), (-1, 0), (0, 1), (0, -1))
                        if (r + dr, q + dq) in cells
                    )
                    if n == 2:
                        corner = (r, q)

        if corner is None:
            continue

        # ray starts just past the corner, away from the L interior
        # It should point generally toward the corresponding dot if possible.
        drs = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
        dot = dots.get(c)

        best_dir = None
        if dot is not None:
            d = (dot[0] - corner[0], dot[1] - corner[1])
            # choose direction matching signs
            for dr, dc in drs:
                if (dr > 0) == (d[0] > 0) and (dc > 0) == (d[1] > 0):
                    best_dir = (dr, dc)
                    break
            if best_dir is None:
                best_dir = (1, 1)
        else:
            best_dir = (1, 1)

        dr, dc = best_dir
        r, q = corner[0] + dr, corner[1] + dc
        while 0 <= r < H and 0 <= q < W:
            out[r, q] = c
            r += dr
            q += dc

        # Also draw the complementary diagonal ray from the dot, if present,
        # in the opposite vertical/horizontal quadrant (this creates the V shape).
        if dot is not None:
            dr2, dc2 = -dr, -dc
            # Start from the dot and stop before overlapping the first segment too far;
            # simply draw until boundary.
            r, q = dot[0], dot[1]
            while 0 <= r < H and 0 <= q < W:
                out[r, q] = c
                r += dr2
                q += dc2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    H, W = a.shape
    out = a.copy()

    # Connected components of each color.
    m_used = np.zeros((H, W), dtype=bool)
    comps = []
    for color in range(1, 10):
        mask = (a == color)
        m = mask.copy()
        while m.any():
            sr, sc = np.argwhere(m)[0]
            stack = [(sr, sc)]
            m[sr, sc] = False
            cells = []
            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < H and 0 <= cc < W and m[rr, cc]:
                        m[rr, cc] = False
                        stack.append((rr, cc))
            comps.append((color, cells))

    shapes = {}
    dots = {}
    for color, cells in comps:
        if len(cells) == 3:
            rs = [r for r, _ in cells]
            cs = [c for _, c in cells]
            if max(rs) - min(rs) == 1 and max(cs) - min(cs) == 1:
                # L shape: find the empty corner of its 2x2 square.
                r0, r1 = min(rs), max(rs)
                c0, c1 = min(cs), max(cs)
                empty = None
                for r in (r0, r1):
                    for c in (c0, c1):
                        if (r, c) not in cells:
                            empty = (r, c)
                            break
                    if empty is not None:
                        break
                shapes[color] = empty
                continue
            if len(cells) == 3:
                # Straight 3-cell segment: keep all endpoints for possible ray.
                shapes[color] = cells

        if len(cells) == 1:
            dots[color] = cells[0]

    def in_grid(r, c):
        return 0 <= r < H and 0 <= c < W

    def paint(r, c, color):
        if in_grid(r, c) and (out[r, c] == 0 or out[r, c] == color):
            out[r, c] = color

    def stop_at_foreign(r, c):
        # Do not paint over existing non-background pixels of another color.
        if in_grid(r, c) and out[r, c] not in (0, color):
            return True
        return False

    def bresenham(r0, c0, r1, c1, color):
        r, c = r0, c0
        dr = abs(r1 - r0)
        dc = abs(c1 - c0)
        sr = 1 if r1 > r0 else -1
        sc = 1 if c1 > c0 else -1
        err = dr - dc
        while True:
            if stop_at_foreign(r, c):
                return
            paint(r, c, color)
            if r == r1 and c == c1:
                return
            e2 = 2 * err
            if e2 > -dc:
                err -= dc
                r += sr
            if e2 < dr:
                err += dr
                c += sc

    def ray45(r0, c0, dr, dc, color):
        r, c = r0 + dr, c0 + dc
        while in_grid(r, c):
            if stop_at_foreign(r, c):
                return
            paint(r, c, color)
            r += dr
            c += dc

    # 1) L shapes paired with a single dot of the same color:
    #    line from the L's empty corner to the dot, then 45-degree continuation.
    for color, empty in list(shapes.items()):
        if isinstance(empty, tuple) and len(empty) == 2 and empty in dots.get(color, set()) is False:
            dot = dots.get(color)
            if dot is None:
                continue
            # Draw from the first step after the empty corner toward the dot.
            r0, c0 = empty
            r1, c1 = dot
            dr = np.sign(r1 - r0)
            dc = np.sign(c1 - c0)
            bresenham(r0 + dr, c0 + dc, r1, c1, color)

            # The extra 45-degree ray goes up-right from the point just before the dot.
            # In the examples this is the penultimate point on the main line.
            # Recompute a simple penultimate point by stepping back one grid step
            # along the dominant Bresenham direction.
            # For these puzzles, the main line always approaches the dot from below/left,
            # so the continuation starts at (dot_row - 1, dot_col - 1) or on the line.
            # More robustly: find the last painted non-dot pixel of this color on the line.
            # Since the line is monotone, use (r1 - dr, c1 - dc) if it is on the line.
            start = (r1 - dr, c1 - dc)
            if in_grid(*start):
                ray45(start[0], start[1], -1, 1, color)

    # 2) Unpaired 3-cell straight segments (Example 3):
    #    emit a 45-degree ray from the endpoint that points toward the next shape/boundary.
    #    Direction is chosen as the unique 45-degree direction from one endpoint
    #    that does not immediately hit another existing pixel.
    for color, cells in shapes.items():
        if isinstance(cells, list):
            rs = [r for r, _ in cells]
            cs = [c for _, c in cells]
            if max(rs) - min(rs) == 0:  # horizontal
                r = rs[0]
                left = (r, min(cs))
                right = (r, max(cs))
            elif max(cs) - min(cs) == 0:  # vertical
                c = cs[0]
                top = (min(rs), c)
                bottom = (max(rs), c)
                # For vertical segments in examples:
                # if there is an L/other shape to the right, ray from middle/top;
                # use both candidate endpoints and choose one that paints new cells.
                candidates = [top, bottom]
            else:
                candidates = [(rs[0], cs[0]), (rs[-1], cs[-1])]

            if isinstance(cells, list) and 'top' in dir() and False:
                pass

            # General fallback: try all 45-degree directions from all endpoints,
            # choose the first that can draw at least one new cell without crossing
            # a foreign pixel immediately.
            endpoints = []
            if max(rs) - min(rs) == 0:
                endpoints = [(r, min(cs)), (r, max(cs))]
            elif max(cs) - min(cs) == 0:
                endpoints = [(min(rs), c), (max(rs), c)]
            else:
                endpoints = [(rs[0], cs[0]), (rs[-1], cs[-1])]

            for (er, ec) in endpoints:
                for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
                    nr, nc = er + dr, ec + dc
                    if not in_grid(nr, nc):
                        continue
                    if out[nr, nc] != 0:
                        continue
                    ray45(er, ec, dr, dc, color)
                    break
                else:
                    continue
                break

    return out.tolist()

