    left_glyphs = [g[1] for g in sorted(glyphs, key=lambda x: (x[2], x[0])) if g[0] == left_col0]
    right_glyphs = [g[1] for g in sorted(glyphs, key=lambda x: (x[2], x[0])) if g[0] == right_col0]
    ordered = left_glyphs + right_glyphs

    # Turtle state.
    cr, cc = start_r, start_c

    for color, pat in ordered:
