        # Identify direction from glyph shape:
        # 3 filled cells in the first row  -> horizontal left
        # 3 filled cells in the last row   -> horizontal right
        # 2 filled cells in the first row  -> vertical down
        row_sums = [sum(row) for row in t]

        if row_sums[0] == 3:
            direction = 'left'
            length = 2
            cr += 1
            for _ in range(length):
                out[cr][cc] = color
                cc -= 1
                cc += 1
                # draw from current entry cell leftwards
            # The loop above was intentionally simple; replace with explicit drawing.
            # Reset cc to entry column and draw properly:
            # (We'll redraw below using a cleaner implementation.)
            pass
        elif row_sums[-1] == 3:
            direction = 'right'
            length = 3
        elif row_sums[0] == 2:
            direction = 'down'
            length = 2
        else:
            # Unknown glyph fallback: vertical length 1.
            direction = 'down'
            length = 1

        if direction in ('left', 'right'):
