                r += 1
            bottom = r

            a = top - 1
            b = bottom + 1
            if a >= 0 and b < H and grid[a][c] == grid[b][c]:
                border_val = grid[a][c]
                if border_val not in (0, v):
                    for rr in range(top, bottom + 1):
                        out[rr][c] = border_val

            r += 1

    return out

