def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Split into rectangular blocks separated by full lines of 6.
    full6_rows = [r for r in range(H) if all(g[r] == 6)]
    full6_cols = [c for c in range(W) if all(g[:, c] == 6)]

    def blocks_along(lines):
        blocks = []
        prev = 0
        for line in lines:
            if line > prev:
                blocks.append((prev, line))
            prev = line + 1
        if prev < len(lines):
            blocks.append((prev, len(lines)))
        return blocks

    row_blocks = blocks_along(full6_rows)
    col_blocks = blocks_along(full6_cols)

    def side_cols(block, side):
        # side: 0 top, 1 bottom -> return set of columns with non-background, non-separator cells
        if side == 0:
            row = block[0][0]
        else:
            row = block[0][1] - 1
        s = set()
        for c in range(block[1][0], block[1][1]):
            v = g[row, c]
            if v != 6 and v != 7:
                s.add(c - block[1][0])
        return s

    def side_rows(block, side):
        # side: 0 left, 1 right -> return set of rows with non-background, non-separator cells
        if side == 0:
            col = block[1][0]
        else:
            col = block[1][1] - 1
        s = set()
        for r in range(block[0][0], block[0][1]):
            v = g[r, col]
            if v != 6 and v != 7:
                s.add(r - block[0][0])
        return s

    # Assign each block a local identity in the original block grid.
    block_ids = []
    for ri, rb in enumerate(row_blocks):
        for ci, cb in enumerate(col_blocks):
            block_ids.append((ri, ci, rb, cb))

    n = len(block_ids)

    def make_edges(orientation):
        """orientation 'V': edges i -> j if bottom(i) matches top(j).
        orientation 'H': edges i -> j if right(i) matches left(j)."""
        adj = [[] for _ in range(n)]
        indeg = [0] * n
        if orientation == 'V':
            features = [side_cols(b, 0) for b in block_ids]
            features_out = [side_cols(b, 1) for b in block_ids]
        else:
            features = [side_rows(b, 0) for b in block_ids]
            features_out = [side_rows(b, 1) for b in block_ids]

        for i in range(n):
            si = features_out[i]
            if not si:
                continue
            for j in range(n):
                if i != j and features[j] == si:
                    adj[i].append(j)
                    indeg[j] += 1
        return adj, indeg

    paths = []
    for orient in ('V', 'H'):
        adj, indeg = make_edges(orient)

        # Find all Hamiltonian paths consistent with a directed path graph.
        # Small block counts make backtracking safe.
        from functools import lru_cache

        def find_paths():
            starts = [i for i in range(n) if indeg[i] == 0]
            if not starts:
                starts = list(range(n))
            results = []

            def dfs(cur, path, remaining):
                if len(path) == n:
                    results.append(path[:])
                    return
                for nxt in adj[cur]:
                    if nxt in remaining:
                        remaining.remove(nxt)
                        path.append(nxt)
                        dfs(nxt, path, remaining)
                        path.pop()
                        remaining.add(nxt)

            for s in starts:
                rem = set(range(n))
                rem.remove(s)
                dfs(s, [s], rem)
            return results

        cand = find_paths()
        if len(cand) == 1:
            paths.append((orient, cand[0]))
        elif len(cand) > 1:
            # Prefer a path that follows a single directed chain with no alternative
            # choices at any step, if one exists.
            def is_deterministic(p):
                seen = set()
                for a, b in zip(p, p[1:]):
                    if b in seen:
                        return False
                    seen.add(b)
                    if len(adj[a]) != 1:
                        return False
                return True

            det = [p for p in cand if is_deterministic(p)]
            if len(det) == 1:
                paths.append((orient, det[0]))
            else:
                paths.append((orient, cand[0]))

    # In all intended cases exactly one orientation gives a unique valid chain.
    if not paths:
        raise ValueError("No unique unfolded chain found")

    orient, order = paths[0]

    # Extract block arrays.
    blocks = {}
    for idx, (ri, ci, rb, cb) in enumerate(block_ids):
        blocks[idx] = g[rb[0]:rb[1], cb[0]:cb[1]].tolist()

    sep_val = 6

    if orient == 'V':
        h = len(order[0])
        w = len(order[0][0])
        out = []
        for k, idx in enumerate(order):
            if k:
                out.append([sep_val] * w)
            out.extend(blocks[idx])
        return out
    else:
        h = len(order[0])
        w = len(order[0][0])
        out = []
        for r in range(h):
            row = []
            for k, idx in enumerate(order):
                if k:
                    row.append(sep_val)
                row.extend(blocks[idx][r])
            out.append(row)
        return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Find full separator lines (entirely 6)
    sep_rows = [r for r in range(H) if all(grid[r][c] == 6 for c in range(W))]
    sep_cols = [c for c in range(W) if all(grid[r][c] == 6 for r in range(H))]

    def get_blocks(lines, total):
        blocks = []
        prev = 0
        for line in lines:
            if line > prev:
                blocks.append((prev, line))
            prev = line + 1
        if prev < total:
            blocks.append((prev, total))
        return blocks

    row_blocks = get_blocks(sep_rows, H)
    col_blocks = get_blocks(sep_cols, W)
    n_rows = len(row_blocks)
    n_cols = len(col_blocks)

    # Extract block contents
    blocks = []
    for (r1, r2) in row_blocks:
        row = []
        for (c1, c2) in col_blocks:
            block = [list(grid[r][c1:c2]) for r in range(r1, r2)]
            row.append(block)
        blocks.append(row)

    if n_rows == 1 and n_cols == 1:
        return [list(row) for row in grid]

    block_h = row_blocks[0][1] - row_blocks[0][0]
    block_w = col_blocks[0][1] - col_blocks[0][0]

    if n_cols == 1:
        # 1D vertical -> horizontal output, reversed (bottom to top)
        out = []
        for r in range(block_h):
            row = []
            for ri in range(n_rows - 1, -1, -1):
                row.extend(blocks[ri][0][r])
                if ri > 0:
                    row.append(6)
            out.append(row)
        return out
    elif n_rows == 1:
        # 1D horizontal -> vertical output, forward (left to right)
        out = []
        for ci in range(n_cols):
            for r in range(block_h):
                out.append(list(blocks[0][ci][r]))
            if ci < n_cols - 1:
                out.append([6] * block_w)
        return out
    elif n_rows == 2 and n_cols == 2:
        # 2x2 -> vertical output, order TL, BR, TR, BL
        order = [(0, 0), (1, 1), (0, 1), (1, 0)]
        out = []
        for idx, (ri, ci) in enumerate(order):
            for r in range(block_h):
                out.append(list(blocks[ri][ci][r]))
            if idx < len(order) - 1:
                out.append([6] * block_w)
        return out
    else:
        raise ValueError(f"Unsupported arrangement: {n_rows}x{n_cols}")

