            colors[a[r, c]] = colors.get(a[r, c], 0) + 1

    bg = max(colors, key=lambda x: colors[x]) if colors else 0
    nonbg = [c for c in colors if c != bg]

    pairs = []
    for color in nonbg:
        cs = comps_8(color)
        for i in range(len(cs)):
            for j in range(i + 1, len(cs)):
                if len(cs[i]) == len(cs[j]) and len(cs[i]) >= 2:
                    pairs.append((color, cs[i], cs[j], pair_bbox(cs[i], cs[j])))

    fill_colors = [c for c in nonbg if len(comps_8(c)) == 1]

    outer = None
    inner = None
    fill_a = None
    fill_b = None

    if len(pairs) >= 2 and len(fill_colors) >= 2:
        # Choose the outermost pair whose bounding box contains at least
        # one other equal-size pair.
        for oc, p1, p2, ob in pairs:
            contains = [
                (ic, q1, q2, ib)
                for ic, q1, q2, ib in pairs
                if ic != oc and ob[0] < ib[0] and ib[1] < ob[1] and ob[2] < ib[2] and ib[3] < ob[3]
            ]
            if contains:
                outer = (oc, ob)
                inner = max(contains, key=lambda x: (x[3][1] - x[3][0] + 1) * (x[3][3] - x[3][2] + 1))
                fill_a = fill_colors[0]
                fill_b = fill_colors[1]
                break

    out = a.copy()

    if outer is not None and inner is not None and fill_a is not None and fill_b is not None:
        oc, ob = outer
        ib = inner[3]

        # Fill the annulus between outer and inner bounding boxes.
        for r in range(ob[0], ob[1] + 1):
            for c in range(ob[2], ob[3] + 1):
                if out[r, c] == bg:
                    if ib[0] <= r <= ib[1] and ib[2] <= c <= ib[3]:
                        continue
                    out[r, c] = fill_a

        # Fill the inner bounding box.
        for r in range(ib[0], ib[1] + 1):
            for c in range(ib[2], ib[3] + 1):
                if out[r, c] == bg:
                    out[r, c] = fill_b

    elif len(pairs) >= 1 and fill_colors:
        # Fallback: fill the bounding box of the largest equal-size pair.
        _, _, _, ob = max(pairs, key=lambda x: (x[3][1] - x[3][0] + 1) * (x[3][3] - x[3][2] + 1))
        for r in range(ob[0], ob[1] + 1):
            for c in range(ob[2], ob[3] + 1):
                if out[r, c] == bg:
                    out[r, c] = fill_colors[0]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.asarray(grid, dtype=int)
    H, W = g.shape

    # background = most frequent colour
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    def components(mask):
        comp_id = np.zeros_like(mask, dtype=int)
        comps = []
        cid = 0
        for r in range(H):
            for c in range(W):
                if mask[r, c] and comp_id[r, c] == 0:
                    cid += 1
                    q = deque([(r, c)])
                    comp_id[r, c] = cid
                    cells = []
                    while q:
                        y, x = q.popleft()
                        cells.append((y, x))
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if mask[ny, nx] and comp_id[ny, nx] == 0:
                                    comp_id[ny, nx] = cid
                                    q.append((ny, nx))
                    comps.append(cells)
        return comps

    non_bg = (g != bg)
    if not non_bg.any():
        return [list(row) for row in grid]

    # gather all solid-colour components
    comps = []
    for colour in np.unique(g[non_bg]):
        for cells in components(g == colour):
            comps.append((int(colour), cells))

    if not comps:
        return [list(row) for row in grid]

    def br_corner(cells):
        return (max(r for r, _ in cells), max(c for _, c in cells))

    # anchor = largest component (keeps its position)
    anchor_col, anchor_cells = max(comps, key=lambda item: len(item[1]))
    anchor_br = br_corner(anchor_cells)

    out = np.full_like(g, bg, dtype=int)

    # place anchor
    for r, c in anchor_cells:
        out[r, c] = anchor_col

    # translate every other component so its BR corner meets the anchor BR corner
    for colour, cells in comps:
        if (colour, cells) == (anchor_col, anchor_cells):
            continue
        comp_br = br_corner(cells)
        dy = anchor_br[0] - comp_br[0]
        dx = anchor_br[1] - comp_br[1]
        for r, c in cells:
            nr, nc = r + dy, c + dx
            if 0 <= nr < H and 0 <= nc < W:
                out[nr, nc] = colour

    return [list(row) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    h, w = len(grid), len(grid[0])

    # Find the vertical separator column made of 6.
    sep = None
    for x in range(w):
        if all(grid[y][x] == 6 for y in range(h)):
            sep = x
            break

    # Fallback: rightmost column whose 6-count is maximal.
    if sep is None:
        counts = [sum(1 for y in range(h) if grid[y][x] == 6) for x in range(w)]
        sep = max(range(w), key=lambda x: counts[x])

    out = np.array([grid[y][sep + 1:] for y in range(h)], dtype=int)
    ow = out.shape[1]

    # Locate the 3x3 stamp pattern in the upper-left area.
    stamp = None
    for y0 in range(0, h - 2):
        for x0 in range(0, sep):
            block = np.array(grid[y0:y0 + 3, x0:x0 + 3])
            vals = set(int(v) for v in block.flatten())
            if 0 not in vals and len(vals) == 2:
                stamp = block
                break
        if stamp is not None:
            break

    if stamp is None:
        return out.tolist()

    # Create the stamp by swapping its two colors.
    c1, c2 = sorted(int(v) for v in stamp.flatten() if v != 0)
    st = np.where(stamp == c1, c2, np.where(stamp == c2, c1, stamp)).astype(int)

    # Use the non-zero pixels below the stamp as a placement mask.
    mask = (np.array(grid, dtype=int) != 0).astype(int)
    mask[:3, :] = 0          # ignore stamp itself
    mask[:, sep:] = 0        # ignore right side / separator

    # Downsample mask to 3x3 blocks.
    bands = (h // 3)
    blocks = (ow // 3)
    coarse = np.zeros((bands, blocks), dtype=int)
    for by in range(bands):
        for bx in range(blocks):
            region = mask[by * 3:by * 3 + 3, bx * 3:bx * 3 + 3]
            if int(region.sum()) > 0:
                coarse[by, bx] = 1

    # Place stamp on every active coarse block.
    for by in range(bands):
        for bx in range(blocks):
            if coarse[by, bx]:
                y0 = by * 3
                x0 = bx * 3
                out[y0:y0 + 3, x0:x0 + 3] = st

    return out.tolist()

