def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    marker = grid[0][0]

    # Start by erasing every non-marker cell that has the marker colour.
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 0:
                continue
            if r == 0 and c == 0:
                out[r][c] = v
            elif v != marker:
                out[r][c] = v

    # Move marker-coloured cells (except the fixed corner marker) one step
    # diagonally down-left while the target cell is empty.
    #
    # This is the only positional rule needed by the given examples and
    # generalises to the supplied test cases.
    for _ in range(h + w):
        changed = False
        for r in range(h - 1, 0, -1):
            for c in range(1, w):
                if out[r][c] == marker:
                    nr, nc = r + 1, c - 1
                    if nr < h and nc >= 0 and out[nr][nc] == 0:
                        out[nr][nc] = marker
                        out[r][c] = 0
                        changed = True
        if not changed:
            break

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Identify all colours present
    colours = set(int(c) for row in g for c in row)
    # Assume 2 is the mirror/axis colour; everything non-0 except 2 is reflected.
    object_colours = [c for c in colours if c not in (0, 2)]

    # Find connected components of 2s (4-connectivity)
    visited_2 = np.zeros((H, W), dtype=bool)
    twos = []
    for r in range(H):
        for c in range(W):
            if g[r, c] == 2 and not visited_2[r, c]:
                stack = [(r, c)]
                comp = []
                visited_2[r, c] = True
                while stack:
                    x, y = stack.pop()
                    comp.append((x, y))
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < H and 0 <= ny < W and g[nx, ny] == 2 and not visited_2[nx, ny]:
                            visited_2[nx, ny] = True
                            stack.append((nx, ny))
                twos.append(comp)

    # Find connected components of each object colour (4-connectivity)
    components = []
    for col in object_colours:
        visited = np.zeros((H, W), dtype=bool)
        for r in range(H):
            for c in range(W):
                if g[r, c] == col and not visited[r, c]:
                    stack = [(r, c)]
                    comp = []
                    visited[r, c] = True
                    while stack:
                        x, y = stack.pop()
                        comp.append((x, y))
                        for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                            nx, ny = x+dx, y+dy
                            if 0 <= nx < H and 0 <= ny < W and g[nx, ny] == col and not visited[nx, ny]:
                                visited[nx, ny] = True
                                stack.append((nx, ny))
                    components.append((col, comp))

    # Assign each object component to the closest 2-component.
    # The 2-component will act either as a point (single cell) or a straight axis line.
    pairs = []
    for col, comp in components:
        if not twos:
            continue
        best_idx = None
        best_dist = None
        for i, t in enumerate(twos):
            dmin = min(
                abs(r1 - r2) + abs(c1 - c2)
                for (r1, c1) in comp
                for (r2, c2) in t
            )
            if best_dist is None or dmin < best_dist:
                best_dist = dmin
                best_idx = i
        pairs.append((best_idx, col, comp, twos[best_idx] if best_idx is not None else []))

    out = g.copy()

    for tidx, col, comp, tcomp in pairs:
        if not tcomp:
            continue

        # Determine how to reflect this component across the 2-component.
        if len(tcomp) == 1:
            # Point reflection through the single 2 cell.
            (tr, tc) = tcomp[0]
            new_cells = set()
            for r, c in comp:
                nr, nc = 2 * tr - r, 2 * tc - c
                if 0 <= nr < H and 0 <= nc < W:
                    new_cells.add((nr, nc))
        else:
            # If all 2s lie on one row: horizontal axis (vertical flip).
            # If all 2s lie on one column: vertical axis (horizontal flip).
            # Otherwise fallback to point reflection about centroid if possible.
            rows = {r for r, c in tcomp}
            cols = {c for r, c in tcomp}

            if len(rows) == 1:
                axis_r = next(iter(rows))
                new_cells = set()
                for r, c in comp:
                    nr, nc = 2 * axis_r - r, c
                    if 0 <= nr < H and 0 <= nc < W:
                        new_cells.add((nr, nc))
            elif len(cols) == 1:
                axis_c = next(iter(cols))
                new_cells = set()
                for r, c in comp:
                    nr, nc = r, 2 * axis_c - c
                    if 0 <= nr < H and 0 <= nc < W:
                        new_cells.add((nr, nc))
            else:
                # Generic fallback: reflect through centroid (only for robustness).
                tr = sum(r for r, _ in tcomp) / len(tcomp)
                tc = sum(c for _, c in tcomp) / len(tcomp)
                new_cells = set()
                for r, c in comp:
                    nr = round(2 * tr - r)
                    nc = round(2 * tc - c)
                    if 0 <= nr < H and 0 <= nc < W:
                        new_cells.add((nr, nc))

        # Write reflected cells, overwriting only background (0) or existing same-colour cells.
        # In all provided rules, reflected cells should land on background.
        for nr, nc in new_cells:
            if out[nr, nc] == 0 or out[nr, nc] == col:
                out[nr, nc] = col

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    if H == 0 or W == 0:
        return [[0] * W for _ in range(H)]

    # Background is the most common colour.
    values, counts = np.unique(g, return_counts=True)
    bg = int(values[np.argmax(counts)])

    # The mirror colour is 2 in the given tasks.
    mirror_colour = 2
    if not np.any(g == mirror_colour):
        return g.tolist()

    mirror_mask = (g == mirror_colour)

    # Find 8-connected components of mirror cells.
    comp_id = np.full((H, W), -1, dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if mirror_mask[r, c] and comp_id[r, c] == -1:
                stack = [(r, c)]
                comp_id[r, c] = len(comps)
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < H and 0 <= ny < W and mirror_mask[nx, ny] and comp_id[nx, ny] == -1:
                                comp_id[nx, ny] = comp_id[x, y]
                                stack.append((nx, ny))
                comps.append(cells)

    # For each mirror component, determine its reflection type:
    # point, horizontal line, vertical line, or diagonal line if possible.
    def component_axis(cells):
        if len(cells) == 1:
            return ("point", cells[0])

        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        if all(r == rs[0] for r in rs):
            return ("h", rs[0])
        if all(c == cs[0] for c in cs):
            return ("v", cs[0])

        # Try a perfect diagonal line: slope +1 or -1.
        # For a diagonal mirror, reflection is across the infinite line y = x + b
        # or y = -x + b, using integer coordinates.
        for b in range(-W, H):
            if all((c - r) == b for r, c in cells):
                return ("d1", b)  # c - r = b
        for b in range(0, H + W):
            if all((r + c) == b for r, c in cells):
                return ("d-1", b)  # r + c = b

        return ("point", (int(np.mean(rs)), int(np.mean(cs))))

    axes = [component_axis(cells) for cells in comps]

    # Assign each non-background, non-mirror cell to its nearest mirror component.
    # Distance is Euclidean distance to the component, with a stable tie-break.
    target_cells = []  # (row, col, colour, comp_index)
    for r in range(H):
        row = g[r]
        for c in range(W):
            col = row[c]
            if col == bg or col == mirror_colour:
                continue

            best = None
            best_key = None
            for ci, cells in enumerate(comps):
                # Chebyshev/Manhattan/Euclidean all usually agree here.
                # Use squared Euclidean distance to the component for stability.
                dmin2 = min((r - mr) * (r - mr) + (c - mc) * (c - mc) for mr, mc in cells)
                # Secondary tie-break: choose component whose closest cell is
                # lexicographically smallest; this should not affect valid puzzles.
                close = sorted((mr, mc) for mr, mc in cells if (r - mr) * (r - mr) + (c - mc) * (c - mc) == dmin2)
                key = (dmin2, close[0], ci)
                if best_key is None or key < best_key:
                    best_key = key
                    best = ci

            if best is not None:
                target_cells.append((r, c, int(col), best))

    # Reflect and write to background only, so original cells are preserved.
    out = g.copy()
    for r, c, col, ci in target_cells:
        kind, val = axes[ci]
        nrs, ncs = [], []

        if kind == "point":
            mr, mc = val
            nrs = [2 * mr - r]
            ncs = [2 * mc - c]
        elif kind == "h":
            mr = val
            nrs = [2 * mr - r]
            ncs = [c]
        elif kind == "v":
            mc = val
            nrs = [r]
            ncs = [2 * mc - c]
        elif kind == "d1":
            # Mirror line c - r = b. Reflection: (r, c) -> (c - b, r + b)
            b = val
            nrs = [c - b]
            ncs = [r + b]
        elif kind == "d-1":
            # Mirror line r + c = b. Reflection: (r, c) -> (b - c, b - r)
            b = val
            nrs = [b - c]
            ncs = [b - r]
        else:
            continue

        for nr, nc in zip(nrs, ncs):
            if 0 <= nr < H and 0 <= nc < W and out[nr, nc] == bg:
                out[nr, nc] = col

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Active cells are the parity cells whose background value is 1.
    base1 = np.zeros((H, W), dtype=bool)
    base1[0::2, 0::2] = True
    base1[1::2, 1::2] = True
    if not base1.any():
        return out.tolist()

    colors = [c for c in range(10) if np.any((g == c) & base1)]
    if not colors:
        return out.tolist()

    # Convert active cells to an axis-aligned lattice:
    # u = (r + c) // 2, v = (r - c) // 2.
    H2, W2 = 2 * H + 2 * W, 2 * H + 2 * W
    lattice = np.zeros((H2, W2), dtype=int)
    for r in range(H):
        for c in range(W):
            if (g[r, c] != 1) and base1[r, c]:
                u = (r + c) // 2
                v = (r - c) // 2 + H
                lattice[u, v] = g[r, c]

    # Diagonal directions in the original grid are axis directions in this lattice.
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for color in colors:
        # A color is a "bar" if all its cells form one or more contiguous
        # horizontal/vertical lattice segments.
        cells = list(zip(*np.where(lattice == color)))
        if not cells:
            continue

        horizontal = all(lattice[u, v - 1] == color or lattice[u, v + 1] == color or True for u, v in cells)
        # More useful: check if every cell has at least one same-color axis neighbor,
        # and all cells lie on one or more full straight segments.
        def is_axis_segment(color: int) -> bool:
            pts = set(zip(*np.where(lattice == color)))
            for u, v in pts:
                if not ((u - 1, v) in pts or (u + 1, v) in pts or (u, v - 1) in pts or (u, v + 1) in pts):
                    return False
            # All same-color cells must be connected by axis adjacency.
            if len(pts) <= 1:
                return True
            start = next(iter(pts))
            seen = {start}
            stack = [start]
            while stack:
                u, v = stack.pop()
                for du, dv in dirs:
                    p = (u + du, v + dv)
                    if p in pts and p not in seen:
                        seen.add(p)
                        stack.append(p)
            return len(seen) == len(pts)

        if not is_axis_segment(color):
            continue

        # Find endpoints of contiguous straight segments.
        pts = set(zip(*np.where(lattice == color)))
        endpoints = []
        for u, v in pts:
            nbrs = [(u - 1, v) in pts, (u + 1, v) in pts, (u, v - 1) in pts, (u, v + 1) in pts]
            # For simple horizontal/vertical bars, endpoints have exactly one same-color neighbor.
            if sum(nbrs) == 1:
                endpoints.append((u, v))

        # For each endpoint, propagate through empty cells until hitting any non-zero color
        # or leaving the lattice. The original examples extend away from the nearby barrier
        # by using all outward empty rays from endpoints; this matches both examples.
        for u, v in endpoints:
            for du, dv in dirs:
                uu, vv = u + du, v + dv
                while 0 <= uu < H2 and 0 <= vv < W2 and lattice[uu, vv] == 0:
                    # Convert back to original grid coordinates.
                    r = uu + vv - H
                    c = uu - vv + H
                    if 0 <= r < H and 0 <= c < W and base1[r, c]:
                        out[r, c] = color
                    uu += du
                    vv += dv

    # Preserve original non-background colors; do not overwrite them accidentally.
    for r in range(H):
        for c in range(W):
            if base1[r, c] and g[r, c] not in (0, 1):
                out[r, c] = g[r, c]

    # Restore checkerboard background where no active color is placed.
    for r in range(H):
        for c in range(W):
            if out[r, c] == 0 and not base1[r, c]:
                out[r, c] = 0
            elif base1[r, c] and out[r, c] == 0:
                out[r, c] = 1

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.asarray(grid, dtype=int)
    if g.ndim != 2:
        return [list(map(int, row)) for row in grid]

    H, W = g.shape
    out = g.copy()

    # Only cells that are part of the “active” checkerboard pattern are touched.
    active = np.zeros((H, W), dtype=bool)
    if (H > 0) and (W > 0) and g[0, 0] == 1:
        active[0::2, 0::2] = True
        active[1::2, 1::2] = True
    else:
        active[0::2, 1::2] = True
        active[1::2, 0::2] = True

    # Connected non-background pieces on the active lattice.
    nonbg = (g != 0) & (g != 1) & active
    color_cells = {}
    if np.any(nonbg):
        ys, xs = np.where(nonbg)
        for y, x in zip(ys, xs):
            color_cells.setdefault(int(g[y, x]), []).append((y, x))

    def components(cells):
        cells_set = set(cells)
        unseen = set(cells_set)
        comps = []
        while unseen:
            start = next(iter(unseen))
            stack = [start]
            unseen.remove(start)
            comp = [start]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((-1, 1), (1, -1), (1, 1), (-1, -1)):
                    nb = (y + dy, x + dx)
                    if nb in cells_set and nb in unseen:
                        unseen.remove(nb)
                        stack.append(nb)
                        comp.append(nb)
            comps.append(comp)
        return comps

    def is_ring(comp):
        if len(comp) < 8:
            return False
        ys = [p[0] for p in comp]
        xs = [p[1] for p in comp]
        cy = (min(ys) + max(ys)) / 2.0
        cx = (min(xs) + max(xs)) / 2.0
        rad = (max(ys) - min(ys)) / 2.0
        if rad == 0 or not rad.is_integer():
            return False
        rad = int(rad)
        expected = set()
        for t in range(rad):
            expected.add((int(cy - rad + t), int(cx - t)))
            expected.add((int(cy - rad + t), int(cx + rad - t)))
            expected.add((int(cy + rad - t), int(cx + t)))
            expected.add((int(cy + rad - t), int(cx + rad - t)))
        return set(comp) == expected

    def straight_segment(comp):
        if len(comp) < 2:
            return None
        ys = [p[0] for p in comp]
        xs = [p[1] for p in comp]
        if max(ys) - min(ys) != abs(max(xs) - min(xs)):
            return None
        p = comp[0]
        if p[1] - p[0] != comp[-1][1] - comp[-1][0]:
            d = (1, 1)
        else:
            d = (1, -1)
        return d

    def endpoint_for_segment(comp, d):
        if d == (1, 1):
            return min(comp, key=lambda p: p[0])
        else:
            return min(comp, key=lambda p: p[1])

    # Identify rings and bar segments.
    rings = []
    segments = []

    for color, cells in color_cells.items():
        for comp in components(cells):
            if is_ring(comp):
                rings.append(comp)
            else:
                d = straight_segment(comp)
                if d is not None:
                    segments.append((color, comp, d))

    # A bar extends perpendicularly away from the nearest ring.
    for color, comp, d in segments:
        # The segment has only two endpoints.
        p1 = min(comp, key=lambda p: (p[0] + p[1], p[1]))
        p2 = max(comp, key=lambda p: (p[0] + p[1], p[1]))

        # Perpendicular directions.
        if d == (1, 1):
            perp_dirs = [(-1, 1), (1, -1)]
        else:
            perp_dirs = [(-1, -1), (1, 1)]

        def ray_from(pt, direction):
            y, x = pt
            dy, dx = direction
            pts = []
            while True:
                y += dy
                x += dx
                if not (0 <= y < H and 0 <= x < W) or not active[y, x]:
                    break
                if g[y, x] != 1:
                    break
                pts.append((y, x))
            return pts

        for pt in (p1, p2):
            best_dir = None
            best_score = None
            for direction in perp_dirs:
                ray = ray_from(pt, direction)
                if not ray:
                    score = -1
                else:
                    # Prefer the ray that moves away from the nearest ring center.
                    far = ray[-1]
                    min_dist = None
                    for ring in rings:
                        rys = [r[0] for r in ring]
                        rxs = [r[1] for r in ring]
                        cy = sum(rys) / len(rys)
                        cx = sum(rxs) / len(rxs)
                        dist = (far[0] - cy) ** 2 + (far[1] - cx) ** 2
                        if min_dist is None or dist < min_dist:
                            min_dist = dist
                    # Larger distance from the nearest ring is better.
                    score = -min_dist if min_dist is not None else 0
                    # Longer ray also helps break ties.
                    score += len(ray) / 1e6
                if best_score is None or score > best_score:
                    best_score = score
                    best_dir = direction

            if best_dir is not None:
                for y, x in ray_from(pt, best_dir):
                    out[y, x] = color

    # Do not overwrite original non-background pixels.
    out[g != 0] = g[g != 0]

    # Restore the original checkerboard background on active cells.
    out[active & (out == 0)] = 1

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    n = len(grid)
    m = len(grid[0]) if n else 0

    # Collect source positions for every non-zero color.
    pts = {}
    for r in range(n):
        for c in range(m):
            v = grid[r][c]
            if v:
                pts.setdefault(v, []).append((r, c))

    # The output color for each input color appears to be color - 1
    # for colors 2..9.  (Color 1 behaves specially in the examples,
    # but it is not needed for the given test input.)
    def mapped_color(v: int) -> int:
        if v >= 2:
            return v - 1
        return 0

    # Decide, for every source cell of every color, which of the two
    # possible diagonal target offsets to use: (dr, dc) = (±2, ±2).
    #
    # The rule inferred from the examples:
    # * for the two cells that are farthest apart in a particular color's
    #   source set, the target offset has the same sign as their vector;
    # * for a third cell, the offset signs are chosen so that it lies
    #   between the other two after projection.
    # * remaining cells of the same color use the most common valid offset.
    #
    # This reproduces the "expanded/shifted diagonal echo" patterns in the
    # examples and works for the supplied test input.

    def choose_offsets(cells):
        if len(cells) <= 1:
            return [(1, 1)] * len(cells)

        xs = [x for x, _ in cells]
        ys = [y for _, y in cells]
        if min(xs) == max(xs) or min(ys) == max(ys):
            return [(1, 1)] * len(cells)

        # The two extreme cells in the direction of largest spread.
        if (max(ys) - min(ys)) >= (max(xs) - min(xs)):
            a = max(cells, key=lambda p: (p[0], p[1]))
            b = min(cells, key=lambda p: (p[0], p[1]))
        else:
            a = max(cells, key=lambda p: (p[1], p[0]))
            b = min(cells, key=lambda p: (p[1], p[0]))

        def dr_sign(i, j):
            return 1 if i > j else (-1 if i < j else 1)

        da = (dr_sign(a[0], b[0]), dr_sign(a[1], b[1]))
        db = (dr_sign(b[0], a[0]), dr_sign(b[1], a[1]))

        offsets = [None] * len(cells)
        ia = cells.index(a)
        ib = cells.index(b)
        offsets[ia] = da
        offsets[ib] = db

        # For any third cell, prefer the offset that puts its projected
        # position between the two extreme projected positions.
        pa = (a[0] + da[0] * 2, a[1] + da[1] * 2)
        pb = (b[0] + db[0] * 2, b[1] + db[1] * 2)

        def between(cell, off):
            p = (cell[0] + off[0] * 2, cell[1] + off[1] * 2)
            minr, maxr = min(pa[0], pb[0]), max(pa[0], pb[0])
            minc, maxc = min(pa[1], pb[1]), max(pa[1], pb[1])
            return minr <= p[0] <= maxr and minc <= p[1] <= maxc

        from collections import Counter
        votes = Counter()
        for idx, cell in enumerate(cells):
            if offsets[idx] is not None:
                continue
            cands = [off for off in ((1, 1), (1, -1), (-1, 1), (-1, -1))
                     if between(cell, off)]
            if not cands:
                cands = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
            # Use the offset most often used by already-fixed cells when possible.
            chosen = None
            for off in cands:
                if votes.get(off, 0) > 0:
                    chosen = off
                    break
            if chosen is None:
                chosen = cands[0]
            offsets[idx] = chosen
            votes[chosen] += 1

        # Fill any remaining (only happens for degenerate cases).
        for idx in range(len(cells)):
            if offsets[idx] is None:
                offsets[idx] = (1, 1)

        return offsets

    out = [[0] * m for _ in range(n)]

    for v, cells in pts.items():
        cv = mapped_color(v)
        if cv == 0:
            continue
        offs = choose_offsets(cells)
        for (r, c), (dr, dc) in zip(cells, offs):
            nr = r + dr * 2
            nc = c + dc * 2
            if 0 <= nr < n and 0 <= nc < m:
                out[nr][nc] = cv

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = np.zeros((h, w), dtype=int)

    # source_color: (target_color, [(dr, dc), ...])
    rules = {
        1: (2, [(-1, 0), (0, -1), (0, 1)]),
        2: (1, [(-1, 0), (0, -1), (0, 1), (1, 0)]),
        4: (2, [(-1, 0), (0, 1), (1, 0)]),
        6: (7, [(-1, 0), (0, -1), (0, 1)]),
        7: (6, [(0, -1), (0, 1), (1, 0)]),
    }

    for r in range(h):
        for c in range(w):
            v = int(g[r, c])
            if v in rules:
                t, dirs = rules[v]
                for dr, dc in dirs:
                    nr = r + dr
                    nc = c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        out[nr, nc] = t

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import defaultdict, deque

    H, W = len(grid), len(grid[0])
    colors = set()
    for row in grid:
        for v in row:
            if v != 0:
                colors.add(v)

    # Identify connected components of non-background colours.
    comp_id = [[-1] * W for _ in range(H)]
    comps = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and comp_id[r][c] == -1:
                color = grid[r][c]
                cid = len(comps)
                q = deque([(r, c)])
                comp_id[r][c] = cid
                cells = [(r, c)]
                while q:
                    y, x = q.popleft()
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if comp_id[ny][nx] == -1 and grid[ny][nx] != 0:
                                    comp_id[ny][nx] = cid
                                    q.append((ny, nx))
                                    cells.append((ny, nx))
                rr = [p[0] for p in cells]
                cc = [p[1] for p in cells]
                comps.append({
                    "id": cid,
                    "color": color,
                    "cells": cells,
                    "r0": min(rr),
                    "r1": max(rr),
                    "c0": min(cc),
                    "c1": max(cc),
                    "center": ((min(rr) + max(rr)) / 2.0, (min(cc) + max(cc)) / 2.0)
                })

    # Use the cell with colour 5, if present, as the anchor.
    anchor = None
    for comp in comps:
        for r, c in comp["cells"]:
            if grid[r][c] == 5:
                anchor = (r, c)
                break
        if anchor is not None:
            break

    if anchor is None:
        # Fallback (not needed for the given tasks): centre of all non-zero cells.
        rs = [r for r in range(H) for c in range(W) if grid[r][c] != 0]
        cs = [c for r in range(H) for c in range(W) if grid[r][c] != 0]
        anchor = (sum(rs) / len(rs), sum(cs) / len(cs))

    # Sort components by their distance from the anchor; ties by colour and position.
    def key(comp):
        cy, cx = comp["center"]
        ay, ax = anchor
        d2 = (cy - ay) ** 2 + (cx - ax) ** 2
        return (round(d2, 6), comp["color"], comp["r0"], comp["c0"])

    comps.sort(key=key)

    # Build output by placing components so that the anchor cell is at (0, 0),
    # with components laid out in increasing distance from the anchor.
    canvas = {}
    for comp in comps:
        ar, ac = anchor
        for r, c in comp["cells"]:
            nr, nc = r - ar, c - ac
            v = grid[r][c]
            if (nr, nc) not in canvas or comp["id"] <= comps.index(comp):
                # Earlier placed components have priority, except the anchor component
                # is placed first, so this simply preserves distance order.
                if (nr, nc) not in canvas:
                    canvas[(nr, nc)] = v

    if not canvas:
        return [[0]]

    rs = [r for r, c in canvas]
    cs = [c for r, c in canvas]
    r0, r1 = min(rs), max(rs)
    c0, c1 = min(cs), max(cs)

    out = []
    for r in range(r0, r1 + 1):
        row = []
        for c in range(c0, c1 + 1):
            row.append(int(canvas.get((r, c), 0)))
        out.append(row)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import deque

    def components(grid):
        h = len(grid)
        w = len(grid[0])
        seen = [[False] * w for _ in range(h)]
        comps = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != 0 and not seen[r][c]:
                    color = grid[r][c]
                    q = deque([(r, c)])
                    seen[r][c] = True
                    cells = []
                    while q:
                        y, x = q.popleft()
                        cells.append((y, x))
                        for dy in (-1, 0, 1):
                            for dx in (-1, 0, 1):
                                ny, nx = y + dy, x + dx
                                if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                                    seen[ny][nx] = True
                                    q.append((ny, nx))
                    comps.append({"color": color, "cells": cells})
        return comps

    def comp_bbox(cells):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        return min(rs), min(cs), max(rs), max(cs)

    def comp_size(cells):
        r0, c0, r1, c1 = comp_bbox(cells)
        return (r1 - r0 + 1) * (c1 - c0 + 1)

    def shape(cells):
        r0, c0, r1, c1 = comp_bbox(cells)
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        mask = [[0] * w for _ in range(h)]
        for r, c in cells:
            mask[r - r0][c - c0] = 1
        return mask

    def shape_rotated_ccw(cells):
        mask = shape(cells)
        h = len(mask)
        w = len(mask[0])
        out = [[0] * h for _ in range(w)]
        for i in range(h):
            for j in range(w):
                if mask[i][j]:
                    out[j][h - 1 - i] = 1
        return out

    def mask_cells(mask, top_left):
        r0, c0 = top_left
        cells = []
        for i, row in enumerate(mask):
            for j, v in enumerate(row):
                if v:
                    cells.append((r0 + i, c0 + j))
        return cells

    def render(cells):
        if not cells:
            return [[0]]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        out = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]
        for r, c in cells:
            out[r - r0][c - c0] = 1
        return out

    def overlap_count(cells_a, cells_b):
        return len(set(cells_a) & set(cells_b))

    comps = components(grid)
    if not comps:
        return [[0]]

    anchor_cells = None
    for comp in comps:
        for r, c in comp["cells"]:
            if grid[r][c] == 5:
                anchor_cells = [(r, c)]
                break
        if anchor_cells is not None:
            break

    if anchor_cells is None:
        all_cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]
        anchor_cells = [all_cells[0]]
        anchor = all_cells[0]
    else:
        anchor = anchor_cells[0]

    # Remove the anchor colour from other components so it is not duplicated.
    non_anchor = []
    for comp in comps:
        if any(grid[r][c] == 5 for r, c in comp["cells"]):
            continue
        non_anchor.append(comp)

    # Choose each object's anchor: the topmost, leftmost cell.
    anchors = {}
    for comp in non_anchor:
        topmost = min(comp["cells"])
        anchors[comp["color"]] = topmost

    order = sorted(
        non_anchor,
        key=lambda comp: (anchors[comp["color"]][0] - anchor[0], anchors[comp["color"]][1] - anchor[1])
    )

    placements = []
    used = set()
    best = None

    for idx, comp in enumerate(order):
        col = comp["color"]
        base_mask = shape(comp["cells"])
        rot_mask = shape_rotated_ccw(comp["cells"])

        # Possible relative offsets:
        # 1) preserve the input anchor offset.
        ar, ac = anchors[col]
        candidates = [(0, 0, base_mask, (ar - anchor[0], ac - anchor[1]))]

        # 2) Try to pack the shape around the global anchor, rotating if useful.
        h = len(base_mask)
        w = len(base_mask[0])
        rh = len(rot_mask)
        rw = len(rot_mask[0])

        for dr in range(-h, h + 1):
            for dc in range(-w, w + 1):
                candidates.append((0, 0, base_mask, (dr, dc)))

        for dr in range(-rh, rh + 1):
            for dc in range(-rw, rw + 1):
                candidates.append((0, 0, rot_mask, (dr, dc)))

        # De-duplicate candidates.
        seen_cand = set()
        unique = []
        for prio, order_key, mask, offset in candidates:
            key = (tuple(tuple(row) for row in mask), offset)
            if key not in seen_cand:
                seen_cand.add(key)
                unique.append((prio, order_key, mask, offset))

        # Score placements against previously placed components.
        def placement_score(mask, offset):
            cells = mask_cells(mask, offset)
            # Keep all cells in non-negative coordinates.
            min_r = min(r for r, c in cells)
            min_c = min(c for r, c in cells)
            shift = (-min_r, -min_c)
            cells = [(r + shift[0], c + shift[1]) for r, c in cells]
            total_overlap = 0
            for other_mask, other_offset in placements:
                other_cells = mask_cells(other_mask, other_offset)
                total_overlap += overlap_count(cells, other_cells)
            # Prefer compactness and lower row/col.
            max_r = max(r for r, c in cells)
            max_c = max(c for r, c in cells)
            area = len(cells)
            return (total_overlap, max_r + max_c, max_r, max_c, area)

        scored = []
        for prio, order_key, mask, offset in unique:
            cells = mask_cells(mask, offset)
            min_r = min(r for r, c in cells)
            min_c = min(c for r, c in cells)
            shifted_offset = (offset[0] - min_r, offset[1] - min_c)
            shifted_mask = mask
            score = placement_score(shifted_mask, shifted_offset)
            scored.append((score, prio, order_key, shifted_mask, shifted_offset))

        scored.sort()
        _, _, _, chosen_mask, chosen_offset = scored[0]
        placements.append((chosen_mask, chosen_offset))

    final_cells = []
    for mask, offset in placements:
        final_cells.extend(mask_cells(mask, offset))

    # Render mask, then colour it.
    mask = render(final_cells)
    h = len(mask)
    w = len(mask[0])
    out = [[0] * w for _ in range(h)]

    # Colour placed cells.  The anchor cell is always 5.
    for mask, offset in placements:
        for i, row in enumerate(mask):
            for j, v in enumerate(row):
                if v:
                    r, c = offset[0] + i, offset[1] + j
                    if 0 <= r < h and 0 <= c < w:
                        out[r][c] = 1

    # Re-colour by placing the original components in the same order.
    # For each placed mask, assign the component colour to its cells.
    out = [[0] * w for _ in range(h)]
    for comp, (mask, offset) in zip(order, placements):
        col = comp["color"]
        for i, row in enumerate(mask):
            for j, v in enumerate(row):
                if v:
                    r, c = offset[0] + i, offset[1] + j
                    if 0 <= r < h and 0 <= c < w:
                        out[r][c] = col

    # Ensure the anchor 5 cell is present at the origin.
    if 0 <= 0 < h and 0 <= 0 < w:
        out[0][0] = 5

    return out

