def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()
    seen = set()

    def add_cell(r, c):
        if 0 <= r < h and 0 <= c < w and g[r, c] == 1:
            seen.add((r, c))

    for r in range(h):
        for c in range(w):
            if g[r, c] != 1:
                continue
            # collect the connected 1-region containing this cell
            cells = [(r, c)]
            stack = [(r, c)]
            add_cell(r, c)
            while stack:
                cr, cc = stack.pop()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and g[nr, nc] == 1 and (nr, nc) not in seen:
                        add_cell(nr, nc)
                        stack.append((nr, nc))
                        cells.append((nr, nc))

            rows = [x for x, _ in cells]
            cols = [x for _, x in cells]
            r1, r2 = min(rows), max(rows)
            c1, c2 = min(cols), max(cols)

            # For each side, look for a contiguous strip of non-background/non-1
            # cells directly adjacent to the 1-region's minimal bounding box.
            candidates = []

            # right side
            if c2 + 1 < w:
                width = r2 - r1 + 1
                rows0, cols0 = r1, c2 + 1
                strip_len = 0
                for k in range(w - c2 - 1):
                    ok = True
                    for i in range(width):
                        v = g[rows0 + i, cols0 + k]
                        if v == 8 or v == 1:
                            ok = False
                            break
                    if not ok:
                        break
                    strip_len += 1
                if strip_len:
                    candidates.append((0, 1, (rows0, cols0, width, strip_len)))

            # left side
            if c1 - 1 >= 0:
                width = r2 - r1 + 1
                rows0, cols0 = r1, c1 - 1
                strip_len = 0
                for k in range(c1):
                    ok = True
                    for i in range(width):
                        v = g[rows0 + i, cols0 - k]
                        if v == 8 or v == 1:
                            ok = False
                            break
                    if not ok:
                        break
                    strip_len += 1
                if strip_len:
                    candidates.append((0, -1, (rows0, cols0, width, strip_len)))

            # bottom side
            if r2 + 1 < h:
                width = c2 - c1 + 1
                rows0, cols0 = r2 + 1, c1
                strip_len = 0
                for k in range(h - r2 - 1):
                    ok = True
                    for i in range(width):
                        v = g[rows0 + k, cols0 + i]
                        if v == 8 or v == 1:
                            ok = False
                            break
                    if not ok:
                        break
                    strip_len += 1
                if strip_len:
                    candidates.append((1, 0, (rows0, cols0, width, strip_len)))

            # top side
            if r1 - 1 >= 0:
                width = c2 - c1 + 1
                rows0, cols0 = r1 - 1, c1
                strip_len = 0
                for k in range(r1):
                    ok = True
                    for i in range(width):
                        v = g[rows0 - k, cols0 + i]
                        if v == 8 or v == 1:
                            ok = False
                            break
                    if not ok:
                        break
                    strip_len += 1
                if strip_len:
                    candidates.append((-1, 0, (rows0, cols0, width, strip_len)))

            if not candidates:
                continue

            # If multiple directions have strips, choose the one with the longest strip.
            candidates.sort(key=lambda x: -x[2][3])
            dr, dc, (rows0, cols0, width, strip_len) = candidates[0]

            # The repeated pattern is the full adjacent strip (strip_len x width).
            if dr == 0:
                # horizontal strip: repeat columns to the left/right
                for k in range(strip_len):
                    if dc == 1:
                        col = cols0 + k
                    else:
                        col = cols0 - k
                    for i in range(width):
                        pat = g[rows0 + i, col]
                        if dc == 1:
                            cc = col + 1
                            while cc < w:
                                out[rows0 + i, cc] = pat
                                cc += 1
                        else:
                            cc = col - 1
                            while cc >= 0:
                                out[rows0 + i, cc] = pat
                                cc -= 1
            else:
                # vertical strip: repeat rows up/down
                for k in range(strip_len):
                    if dr == 1:
                        row = rows0 + k
                    else:
                        row = rows0 - k
                    for i in range(width):
                        pat = g[row, cols0 + i]
                        if dr == 1:
                            rr = row + 1
                            while rr < h:
                                out[rr, cols0 + i] = pat
                                rr += 1
                        else:
                            rr = row - 1
                            while rr >= 0:
                                out[rr, cols0 + i] = pat
                                rr -= 1

    return out

