        return out.tolist()

    # Fillable target cells: the 3x3 block around the 2
    targets = [(r, c) for r in range(r0 - 1, r0 + 2)
                       for c in range(c0 - 1, c0 + 2)
                       if 0 <= r < H and 0 <= c < W and a[r, c] in (2, 3)]

    # Sources: all 9s outside the 3x3 block
    sources = [(r, c) for r in range(H) for c in range(W)
               if a[r, c] == 9 and not (r0 - 1 <= r <= r0 + 1 and c0 - 1 <= c <= c0 + 1)]

    # Distances from each target to all reachable cells, avoiding 6 walls.
    # BFS goes outward from each target.
    dist = {}
    for tr, tc in targets:
        d = -1
