        while q:
            r, c = q.popleft()
            if (r, c) in d:
                continue
            d[(r, c)] = dist_tr = len(q) - 1  # not used directly; use actual BFS level below
        # Redo with level BFS for clarity
    # Simpler level BFS per target:
    dist = {}
    for tr, tc in targets:
        d = {}
        d[(tr, tc)] = 0
        q = deque([(tr, tc)])
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and a[nr, nc] != 6 and (nr, nc) not in d:
                    d[(nr, nc)] = d[(r, c)] + 1
                    q.append((nr, nc))
        dist[(tr, tc)] = d

    # For every source and every target, if reachable, make a candidate pair.
    # Choose the globally shortest source-target connections first.
    candidates = []
    for sr, sc in sources:
        for (tr, tc), d in dist.items():
            if (sr, sc) in d:
                candidates.append((d[(sr, sc)], sr, sc, tr, tc))
    candidates.sort()

    used_sources = set()
    used_targets = set()
    for _, sr, sc, tr, tc in candidates:
        if (sr, sc) in used_sources or (tr, tc) in used_targets:
            continue
        used_sources.add((sr, sc))
        used_targets.add((tr, tc))
        out[sr, sc] = 7
        out[tr, tc] = 9

