from collections import Counter, deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Determine the background colour: the colour most frequently touching the border.
    border_counts = Counter()
    for c in range(w):
        border_counts[grid[0][c]] += 1
        border_counts[grid[h - 1][c]] += 1
    for r in range(h):
        border_counts[grid[r][0]] += 1
        border_counts[grid[r][w - 1]] += 1

    bg = None
    if border_counts:
        bg = max(border_counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]
    else:
        bg = max(Counter(v for row in grid for v in row).items(), key=lambda kv: (kv[1], -kv[0]))[0]

    # Candidate "special" colours: non-background colours that occur exactly once.
    cnt = Counter(v for row in grid for v in row)
    special_cells = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg and cnt[v] == 1:
                special_cells.append((r, c, v))

    # Choose the special colour.  The examples all have a unique such colour.
    # If several occur, choose the first one in row-major order; this handles
    # constructed cases with extra singleton decoys deterministically.
    special = None
    if special_cells:
        special_cells.sort()
        special = special_cells[0][2]
    else:
        # Fallback (should not be needed for valid inputs): use the least frequent
        # non-background colour, breaking ties by smallest colour value.
        nonbg = [(v, n) for v, n in cnt.items() if v != bg]
        if nonbg:
            special = min(nonbg, key=lambda x: (x[1], x[0]))[0]
        else:
            return out

    if special is None:
        return out

    # Find all background cells not connected to the border background.
    # These are the enclosed holes and are filled with the special colour.
    seen = [[False] * w for _ in range(h)]
    q = deque()

    for c in range(w):
        if grid[0][c] == bg and not seen[0][c]:
            seen[0][c] = True
            q.append((0, c))
        if grid[h - 1][c] == bg and not seen[h - 1][c]:
            seen[h - 1][c] = True
            q.append((h - 1, c))

    for r in range(h):
        if grid[r][0] == bg and not seen[r][0]:
            seen[r][0] = True
            q.append((r, 0))
        if grid[r][w - 1] == bg and not seen[r][w - 1]:
            seen[r][w - 1] = True
            q.append((r, w - 1))

    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if not seen[nr][nc] and grid[nr][nc] == bg:
                    seen[nr][nc] = True
                    q.append((nr, nc))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and not seen[r][c]:
                out[r][c] = special

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Background is the colour that touches the border most often.
    border_counts = {}
    for c in range(w):
        v = grid[0][c]
        border_counts[v] = border_counts.get(v, 0) + 1
        v = grid[h - 1][c]
        border_counts[v] = border_counts.get(v, 0) + 1
    for r in range(h):
        v = grid[r][0]
        border_counts[v] = border_counts.get(v, 0) + 1
        v = grid[r][w - 1]
        border_counts[v] = border_counts.get(v, 0) + 1
    bg = max(border_counts, key=lambda x: (border_counts[x], -x)) if border_counts else 0

    # The fill colour is the unique non-background singleton present in the grid.
    total_counts = {}
    for row in grid:
        for v in row:
            total_counts[v] = total_counts.get(v, 0) + 1

    fill_color = None
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg and total_counts[v] == 1:
                fill_color = v
                break
        if fill_color is not None:
            break

    if fill_color is None:
        # Fallback, should not be needed for valid ARC inputs.
        candidates = [(v, n) for v, n in total_counts.items() if v != bg]
        if candidates:
            fill_color = min(candidates, key=lambda x: (x[1], x[0]))[0]
        else:
            return out

    # Mark all background cells connected to the border by 4-neighbour moves.
    seen = [[False] * w for _ in range(h)]
    stack = []

    def add(r, c):
        if 0 <= r < h and 0 <= c < w and not seen[r][c] and grid[r][c] == bg:
            seen[r][c] = True
            stack.append((r, c))

    for c in range(w):
        add(0, c)
        add(h - 1, c)
    for r in range(h):
        add(r, 0)
        add(r, w - 1)

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            add(r + dr, c + dc)

    # Fill only background cells that are not border-connected.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and not seen[r][c]:
                out[r][c] = fill_color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape

    def neighbors(mask, r, c):
        res = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and mask[nr, nc]:
                res.append((nr, nc))
        return res

    # For every color, consider each 4-connected component.
    visited = np.zeros((h, w), dtype=bool)
    out = a.copy()

    for r in range(h):
        for c in range(w):
            val = a[r, c]
            if val == 0 or visited[r, c]:
                continue

            # collect component of this color
            mask = np.zeros((h, w), dtype=bool)
            stack = [(r, c)]
            visited[r, c] = True
            mask[r, c] = True

            while stack:
                cr, cc = stack.pop()
                for nr, nc in neighbors(mask, cr, cc):
                    if a[nr, nc] == val and not visited[nr, nc]:
                        visited[nr, nc] = True
                        mask[nr, nc] = True
                        stack.append((nr, nc))

            # If the component is not "noisy" (small), leave it unchanged.
            # The examples remove only cells from components large enough
            # to contain 3 or more removable endpoints.
            cells = list(zip(*np.where(mask)))
            if len(cells) < 10:
                continue

            to_remove = set()

            # Iteratively prune 4-neighbor endpoints.
            for _ in range(3):
                changed = False
                current = [(r, c) for r, c in cells if (r, c) not in to_remove]
                for r, c in current:
                    live_neighbors = [
                        (nr, nc)
                        for (nr, nc) in neighbors(mask, r, c)
                        if (nr, nc) not in to_remove
                    ]
                    if len(live_neighbors) == 1:
                        to_remove.add((r, c))
                        changed = True

                if not changed:
                    break

            for r, c in to_remove:
                out[r, c] = 0

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    if a.size == 0:
        return []

    h, w = a.shape
    out = a.copy()

    # Background is the color of the border. In all provided cases this works.
    background = int(a[0, 0])
    # If border is not uniform, still use the most frequent border color.
    border_vals = np.concatenate((a[0, :], a[-1, :], a[:, 0], a[:, -1]))
    vals, counts = np.unique(border_vals, return_counts=True)
    background = int(vals[np.argmax(counts)])

    # Precompute connected components for every non-background color.
    visited = np.zeros((h, w), dtype=bool)
    components = []

    for r in range(h):
        for c in range(w):
            if visited[r, c] or a[r, c] == background:
                continue

            color = int(a[r, c])
            mask = np.zeros((h, w), dtype=bool)
            stack = [(r, c)]
            visited[r, c] = True
            mask[r, c] = True

            while stack:
                cr, cc = stack.pop()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if not visited[nr, nc] and a[nr, nc] == color:
                            visited[nr, nc] = True
                            mask[nr, nc] = True
                            stack.append((nr, nc))

            cells = set(zip(*np.where(mask)))
            components.append((color, cells))

    def degree(cell, allowed):
        r, c = cell
        d = 0
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (nr, nc) in allowed:
                d += 1
        return d

    for color, cells in components:
        if len(cells) <= 1:
            continue

        current = set(cells)
        removed = set()

        # Iteratively prune endpoints (0 or 1 same-color 4-neighbors).
        while True:
            endpoints = {x for x in current if degree(x, current) <= 1}
            if not endpoints:
                break
            current -= endpoints
            removed |= endpoints

        # Keep the core only if it is non-empty and the original component was
        # not merely a tiny dangling branch.
        if current and len(removed) < len(cells):
            for x in removed:
                out[x[0], x[1]] = background

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    arr = np.array(grid, dtype=int)
    H, W = arr.shape

    # Find the "filler" color:
    # - not 0
    # - appears in small, scattered components (typically 1-cell blobs)
    # - not a rectangular-border color
    # This is robust for the provided examples and the test style.

    def components_of_color(c):
        seen = np.zeros((H, W), dtype=bool)
        comps = []
        for i in range(H):
            for j in range(W):
                if arr[i, j] == c and not seen[i, j]:
                    stack = [(i, j)]
                    seen[i, j] = True
                    cells = []
                    while stack:
                        x, y = stack.pop()
                        cells.append((x, y))
                        for nx, ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                            if 0 <= nx < H and 0 <= ny < W:
                                if not seen[nx, ny] and arr[nx, ny] == c:
                                    seen[nx, ny] = True
                                    stack.append((nx, ny))
                    comps.append(cells)
        return comps

    def bbox(cells):
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        return min(ys), max(ys), min(xs), max(xs)

    def is_border_color(c):
        cells = []
        for i in range(H):
            row = arr[i]
            for j in range(W):
                if row[j] == c:
                    cells.append((i, j))
        if len(cells) < 8:
            return False, 0, 0, 0, 0, 0

        r0, r1, c0, c1 = bbox(cells)
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if h < 3 or w < 3:
            return False, 0, 0, 0, 0, 0

        rect = set()
        for y in range(r0, r1 + 1):
            rect.add((y, c0))
            rect.add((y, c1))
        for x in range(c0, c1 + 1):
            rect.add((r0, x))
            rect.add((r1, x))

        # Allow missing border cells where other frames/noise intersect.
        # But the vast majority of the bounding rectangle perimeter must be present.
        on_rect = sum(1 for p in rect if arr[p[0], p[1]] == c)
        perimeter = 2 * (h + w) - 4
        if perimeter == 0:
            return False, 0, 0, 0, 0, 0
        if on_rect / perimeter < 0.55:
            return False, 0, 0, 0, 0, 0

        # It should not be a tiny solid blob.
        if len(cells) > 0.85 * (h * w) and min(h, w) > 4:
            return False, 0, 0, 0, 0, 0

        area = h * w
        return True, r0, r1, c0, c1, area

    border_colors = []
    meta = {}
    for c in range(1, 10):
        if not np.any(arr == c):
            continue
        ok, r0, r1, c0, c1, area = is_border_color(c)
        if ok:
            border_colors.append(c)
            meta[c] = (r0, r1, c0, c1, area)

    # Sort border colors by increasing bounding-box area.
    border_colors.sort(key=lambda c: (meta[c][4], meta[c][0], meta[c][2], c))

    # Choose filler: most common non-border color that has at least one
    # connected component of size 1 (scattered noise), else most common
    # non-border non-zero color.
    candidate_fillers = []
    for c in range(1, 10):
        if c in border_colors or not np.any(arr == c):
            continue
        comps = components_of_color(c)
        single = any(len(comp) == 1 for comp in comps)
        if single:
            candidate_fillers.append((np.sum(arr == c), c))

    if candidate_fillers:
        filler = max(candidate_fillers, key=lambda x: (x[0], -x[1]))[1]
    else:
        # Fallback
        best = (0, 5)
        for c in range(1, 10):
            if c in border_colors:
                continue
            cnt = int(np.sum(arr == c))
            if cnt > best[0]:
                best = (cnt, c)
        filler = best[1]

    # Output is a lower-triangular style table:
    # row i has its label in the first min(i+1, 4) columns,
    # remaining columns are the filler color.
    Wout = 4
    out = []
    for i, c in enumerate(border_colors):
        row = [c] * min(i + 1, Wout) + [filler] * max(0, Wout - (i + 1))
        out.append(row)

    # If, for any reason, no border colors were found, fall back to a safe
    # constant filler grid (not expected for valid inputs).
    if not out:
        out = [[filler] * Wout for _ in range(4)]

    return [list(map(int, row)) for row in out]

