def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.asarray(grid, dtype=int)
    H, W = a.shape

    def bbox(cells):
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        return min(ys), max(ys), min(xs), max(xs)

    def border_ok(cells, r0, r1, c0, c1):
        # A usable rectangular frame should have enough border pixels
        # and must not be a solid filled block.
        if len(cells) < 8:
            return False

        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if h < 3 or w < 3:
            return False

        expected = 2 * (h + w) - 4
        have = 0
        for y in range(r0, r1 + 1):
            if a[y, c0] in (0, 1, 2):
                have += 1
            if c1 != c0 and a[y, c1] in (0, 1, 2):
                have += 1
        for x in range(c0, c1 + 1):
            if a[r0, x] in (0, 1, 2):
                have += 1
            if r1 != r0 and a[r1, x] in (0, 1, 2):
                have += 1

        if have < 0.55 * expected:
            return False
        if len(cells) > 0.82 * (h * w):
            return False
        return True

    # Identify the frame colours.  In all observed cases the frames are
    # colours 1,2,3,4,8; 5,7,9 are noise/fillers.
    frames = []
    for c in (1, 2, 3, 4, 8):
        cells = np.argwhere(a == c)
        if len(cells) == 0:
            continue
        cells = [tuple(p) for p in cells]
        r0, r1, c0, c1 = bbox(cells)
        if border_ok(cells, r0, r1, c0, c1):
            frames.append((r0, r1, c0, c1, c))

    if not frames:
        # Very defensive fallback: any colour that can form a rectangle.
        for c in range(1, 10):
            cells = np.argwhere(a == c)
            if len(cells) == 0:
                continue
            cells = [tuple(p) for p in cells]
            r0, r1, c0, c1 = bbox(cells)
            if border_ok(cells, r0, r1, c0, c1):
                frames.append((r0, r1, c0, c1, c))

    # Sort the frames by the vertical center of their bounding box.
    # Ties are broken by horizontal center, then leftmost column, then color.
    frames.sort(key=lambda t: ((t[0] + t[1]) / 2.0,
                               (t[2] + t[3]) / 2.0,
                               t[2],
                               t[4]))
    order = [t[4] for t in frames]

    # The filler is the dominant non-frame colour in the input.
    fill = 0
    best = -1
    for c in range(1, 10):
        if c in order:
            continue
        cnt = int(np.sum(a == c))
        if cnt > best:
            best = cnt
            fill = c

    # Canonical output: an N x 4 lower-triangular block.
    # Row i contains color order[i] in the first i+1 columns.
    out = []
    for i, c in enumerate(order):
        k = min(i + 1, 4)
        row = [c] * k + [fill] * (4 - k)
        out.append(row)

    return out

