def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = a.copy()

    # Detect the 5x11 hollow rectangular frames.
    frames = []
    for r in range(h - 4):
        for c in range(w - 10):
            border = a[r, c]
            if border == 0:
                continue
            top = a[r, c:c + 11]
            bot = a[r + 4, c:c + 11]
            if top.min() != border or top.max() != border:
                continue
            if bot.min() != border or bot.max() != border:
                continue
            left = a[r + 1:r + 4, c]
            right = a[r + 1:r + 4, c + 10]
            if left.min() != border or left.max() != border:
                continue
            if right.min() != border or right.max() != border:
                continue
            interior = a[r + 1:r + 4, c + 1:c + 10]
            if interior.min() != interior.max():
                continue
            bg = int(interior.min())
            if border == bg:
                continue
            frames.append((r, c, border, bg))

    if not frames:
        return a.tolist()

    # Keep only the frames and their original background.
    for r, c, border, bg in frames:
        out[r, c:c + 11] = border
        out[r + 4, c:c + 11] = border
        out[r + 1:r + 4, c] = border
        out[r + 1:r + 4, c + 10] = border
        out[r + 1:r + 4, c + 1:c + 10] = bg

    def in_any_frame(rr, cc):
        for r, c, _, _ in frames:
            if r <= rr <= r + 4 and c <= cc <= c + 10:
                return True
        return False

    # For each frame, project external pixels of the same colour into its
    # centre row, wrapping the column coordinate modulo the frame width.
    for r, c, border, bg in frames:
        mid = r + 2
        mask = (a == border)
        if not mask.any():
            continue
        rows, cols = np.where(mask)
        for rr, cc in zip(rows, cols):
            if in_any_frame(int(rr), int(cc)):
                continue
            new_cc = c + (int(cc) - c) % 11
            out[mid, new_cc] = border

    return out

