def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Output glyph used for a digit: each source at (r, c) places this
    # 4x4 pattern with its top-left corner at (r, c).
    glyphs = {
        2: [
            "4444",
            "4004",
            "4004",
            "4444",
        ],
        3: [
            "0110",
            "1001",
            "1001",
            "0110",
        ],
        5: [
            "6600",
            "6600",
            "0066",
            "0066",
        ],
        8: [
            "7007",
            "0770",
            "0770",
            "7007",
        ],
    }

    def stamp(out, r, c, glyph):
        for dr in range(4):
            rr = r + dr
            if not (0 <= rr < h):
                continue
            row = out[rr]
            for dc in range(4):
                cc = c + dc
                if 0 <= cc < w:
                    row[cc] = int(glyph[dr][dc])

    out = [[0] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v in glyphs:
                stamp(out, r, c, glyphs[v])

    return out

