    h = len(grid)
    w = len(grid[0])

    keys = {2, 3, 5, 8}

    patterns = {
        2: (4, [
            [4, 4, 4, 4],
            [4, 0, 0, 4],
            [4, 0, 0, 4],
            [4, 4, 4, 4],
        ]),
