        ]),
        8: (7, [
            [7, 0, 0, 7],
            [0, 7, 7, 0],
            [0, 7, 7, 0],
            [7, 0, 0, 7],
        ]),
    }

    out = [[0] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] not in keys:
